type BlackcrabNativeBridge = Readonly<{
  apiVersion: 1;
  pickFolder: LocalApi["dialogs"]["pickFolder"];
  openExternal: (url: string) => Promise<boolean>;
}>;

declare global {
  interface Window {
    readonly blackcrabNative?: BlackcrabNativeBridge;
  }
}

function readBlackcrabNativeBridge(): BlackcrabNativeBridge | undefined {
  const bridge = typeof window === "undefined" ? undefined : window.blackcrabNative;
  return bridge?.apiVersion === 1 &&
    typeof bridge.pickFolder === "function" &&
    typeof bridge.openExternal === "function"
    ? bridge
    : undefined;
}

export function hasBlackcrabNativeBridge(): boolean {
  return readBlackcrabNativeBridge() !== undefined;
}

